   "blurb": "前 2400 年，拉格什与乌玛为灌溉渠反复开战，两河政治始终围绕水源展开。",
   "detail": "拉格什与乌玛为底格里斯-幼发拉底之间的灌溉渠与边界长期冲突，双方以神的名义立约又反复毁约。水权争端消耗了城邦的军力与财力，也给了北方阿卡德势力介入的机会。灌溉农业的脆弱性，使两河政治始终围绕水源展开。两国为一条灌溉渠与边界田地反复开战，界碑与盟约被反复推翻，鹫碑即为此事而立。",
