   "detail": "铁斧与铁犁的普及使恒河平原的森林与沼泽得以开垦，水稻种植与人口增长加速。雅利安人的中心从印度河上游东移到恒河流域，出现定居村落与陶器文化。恒河由此成为印度政治与宗教的新轴心。森林砍伐与水稻耕作改变了恒河两岸的地貌。铁斧可砍伐密林、铁犁可翻耕黏土，稻作与村落随之向东推进，恒河流域成为新的政治中心。",
