   "blurb": "前 1100 年，腓尼基把文字简化为二十二个辅音字母，成为欧洲字母表的远祖。",
   "detail": "腓尼基书吏把楔形与象形符号简化成二十二个辅音字母，用极少的笔画记录语言。这套字母随商船传遍地中海，希腊人加入元音后形成希腊字母，再由罗马人传成拉丁字母。它是最早被广泛使用的音素文字，也是今日欧洲字母表的远祖。铭文以二十二个辅音符号刻写，不再借助楔形或圣书体，这套字母后来经希腊人加入元音，成为欧洲字母的祖先。",
