   "detail": "传说推罗公主狄多率移民在北非海岸建立迦太基（Qart-Hadasht，「新城」）。它凭港湾与腹地农业迅速壮大，随后在撒丁岛、西西里西部、西班牙南部设商站与殖民地，控制西地中海的金属与奴隶贸易，后来与罗马争霸百余年。推罗公主狄多（埃利萨）率移民在北非海岸建城，此后迦太基沿西地中海设商站、夺港口，成为推罗之后最强大的腓尼基城邦。",
