   "detail": "阿克巴把军官与官员编入「曼萨布达尔」等级，按骑兵数定额定薪，薪俸以「扎吉尔」（土地税收）支付。制度把军事、行政与税收绑定，既保证兵源，也便于中央调动。后期扎吉尔世袭化，成为地方势力坐大的根源。按军功与品级授予曼萨布达尔身份，配给相应骑兵；其俸禄以扎吉尔（土地税收）支付，帝国据此建立不需现金的军政体系。",
