   "detail": "在欧文、皮尔与议会调查委员会的推动下，1833年《工厂法》规定纺织厂不得雇用九岁以下儿童，九至十三岁每日工时不超过八小时，并设立四名国家监察员。这是国家首次以立法直接干预工厂的劳动条件，此前靠的是家长式雇主与地方治安法官的自愿裁量。",
