   "detail": "1799 年法军在埃及罗塞塔镇修筑工事时发现石碑，上面刻有同一诏书的圣书体、世俗体与希腊文三种文字。1801 年英军接管石碑送入大英博物馆。1822 年商博良以王名圈与科普特语比对宣布破译，埃及三千年文献重获可读性，埃及学由此诞生，也让欧洲重新认识东方文明。石碑以三种文字刻同一敕令，商博良据此破译圣书体，埃及学由此诞生。",
